export function parseVersion(text) {
  const m = typeof text === 'string' && pattern.exec(text);
  if (!m) throw new Error('invalid version');
  const prerelease = m[4] ? m[4].split('.') : [];
  if (prerelease.some(p => /^0[0-9]+$/.test(p))) throw new Error('invalid version');
  return {major: Number(m[1]), minor: Number(m[2]), patch: Number(m[3]), prerelease};
}
const cmp = (a,b) => a < b ? -1 : a > b ? 1 : 0;
export function compareVersions(a,b) {
  const x = parseVersion(a), y = parseVersion(b);
  // Compare original integer strings to avoid precision loss for large components.
  const ax = a.split('-')[0].split('.'), by = b.split('-')[0].split('.');
  for (let i=0;i<3;i++) { const c = cmp(BigInt(ax[i]),BigInt(by[i])); if (c) return c; }
  if (!x.prerelease.length || !y.prerelease.length) return cmp(!x.prerelease.length,!y.prerelease.length);
  for (let i=0;i<Math.min(x.prerelease.length,y.prerelease.length);i++) {
    const p=x.prerelease[i], q=y.prerelease[i], pn=/^[0-9]+$/.test(p), qn=/^[0-9]+$/.test(q);
    const c = pn && qn ? cmp(BigInt(p),BigInt(q)) : pn !== qn ? (pn ? -1 : 1) : cmp(p,q);
    if(c) return c;
  }
  return cmp(x.prerelease.length,y.prerelease.length);
}
"}

{"path":"src/csv.mjs","content":"export function parseCSV(text) {
  if (typeof text !== 'string') throw new Error('CSV must be text');
  if (!text.length) return [];
  const rows=[]; let row=[], field='', state='start', ended=false;
  for(let i=0;i<text.length;i++) {
    const c=text[i]; ended=false;
    if(state==='quoted') {
      if(c==='"') { if(text[i+1]==='"') {field+='"';i++;} else state='closed'; }
      else field+=c;
      continue;
    }
    if(c===',' || c==='\r' || c==='\n') {
      row.push(field); field=''; state='start';
      if(c!==',') { rows.push(row);row=[];ended=true;if(c==='\r' && text[i+1]==='\n') i++; }
    } else if(c==='"' && state==='start') state='quoted';
    else { if(c==='"' || state==='closed') throw new Error('invalid CSV quote'); field+=c;state='plain'; }
  }
  if(state==='quoted') throw new Error('unclosed CSV quote');
  if(!ended) {row.push(field);rows.push(row);}
  return rows;
}
export function stringifyCSV(rows) {
  return rows.map(row=>row.map(value=>{
    const s=String(value); return /[",\r\n]/.test(s) ? '"'+s.replaceAll('"','""')+'"' : s;
  }).join(',')).join('\r\n');
}
"}

{"path":"src/catalog.mjs","content":"import {parseVersion} from './version.mjs';
const copy = r => ({...r,tags:[...r.tags],dependencies:[...r.dependencies]});
const object = x => x !== null && typeof x === 'object' && !Array.isArray(x);
export function normalizeRecord(r) {
  if(!object(r) || typeof r.id!=='string' || !r.id.trim() || typeof r.name!=='string' || !r.name.trim()) throw new Error('invalid record id/name');
  parseVersion(r.version);
  for(const key of ['tags','dependencies']) if(!Array.isArray(r[key]) || r[key].some(v=>typeof v!=='string')) throw new Error('invalid '+key);
  if(r.dependencies.some(v=>!v.trim())) throw new Error('invalid dependency id');
  return {id:r.id.trim(),name:r.name.trim(),version:r.version,tags:[...new Set(r.tags.map(t=>t.trim().toLowerCase()).filter(Boolean))].sort(),dependencies:[...new Set(r.dependencies)]};
}
export function createCatalog(seed=[]) {
  if(!Array.isArray(seed)) throw new Error('invalid seed');
  let entries=new Map();
  function add(map,r) {const n=normalizeRecord(r);if(map.has(n.id)) throw new Error('duplicate id: '+n.id);map.set(n.id,n);return copy(n);}
  function update(map,id,patch) {
    if(!map.has(id)) throw new Error('unknown id: '+id);
    if(!object(patch) || ('id' in patch && patch.id!==id)) throw new Error('invalid patch/id change');
    const n=normalizeRecord({...map.get(id),...patch});map.set(id,n);return copy(n);
  }
  seed.forEach(r=>add(entries,r));
  return {
    list:()=>[...entries.keys()].sort().map(id=>copy(entries.get(id))),
    get:id=>entries.has(id)?copy(entries.get(id)):null,
    add:r=>add(entries,r), update:(id,p)=>update(entries,id,p),remove:id=>entries.delete(id),
    applyBatch(operations) {
      if(!Array.isArray(operations)) throw new Error('invalid operations');
      const draft=new Map(entries);
      const results=operations.map(op=>{
        if(!object(op)) throw new Error('invalid operation');
        if(op.type==='add') return add(draft,op.record);
        if(typeof op.id!=='string' || !op.id.trim()) throw new Error('invalid operation id');
        if(op.type==='update') return update(draft,op.id,op.patch);
        if(op.type==='remove') return draft.delete(op.id);
        throw new Error('invalid operation');
      });
      entries=draft;return results;
    }
  };
}
"}

{"path":"src/search.mjs","content":"import {compareVersions,parseVersion} from './version.mjs';
export function searchRecords(records,query={}) {
  if(!query || typeof query!=='object' || Array.isArray(query)) throw new Error('invalid query');
  const {sortBy='id',order='asc',offset=0,limit=20,text='',tags=[] ,versionMin,versionMax}=query;
  if(!['id','name','version'].includes(sortBy) || !['asc','desc'].includes(order)) throw new Error('invalid sort/order');
  if(!Number.isInteger(offset)||offset<0||!Number.isInteger(limit)||limit<1||limit>100) throw new Error('invalid paging');
  if(typeof text!=='string'||!Array.isArray(tags)||tags.some(t=>typeof t!=='string')) throw new Error('invalid text/tags');
  if(versionMin!==undefined) parseVersion(versionMin);
  if(versionMax!==undefined) parseVersion(versionMax);
  const needle=text.trim().toLowerCase(), wanted=[...new Set(tags.map(t=>t.trim().toLowerCase()).filter(Boolean))];
  const items=records.filter(r=>(r.id.toLowerCase().includes(needle)||r.name.toLowerCase().includes(needle)) && wanted.every(t=>r.tags.map(v=>v.trim().toLowerCase()).includes(t)) && (versionMin===undefined||compareVersions(r.version,versionMin)>=0) && (versionMax===undefined||compareVersions(r.version,versionMax)<=0));
  const cmp=(a,b)=>a<b?-1:a>b?1:0;
  items.sort((a,b)=> (order==='asc'?1:-1)*(sortBy==='version'?compareVersions(a.version,b.version):cmp(a[sortBy],b[sortBy])) || cmp(a.id,b.id));
  return {items:items.slice(offset,offset+limit).map(r=>structuredClone(r)),total:items.length,offset,limit};
}
"}

{"path":"src/graph.mjs","content":"export function planDependencies(records,requestedIds) {
  if(!Array.isArray(requestedIds)||requestedIds.some(id=>typeof id!=='string')) throw new Error('invalid requested ids');
  const map=new Map(records.map(r=>[r.id,r])), done=new Set(), active=[], result=[];
  function visit(id) {
    if(done.has(id)) return;
    if(active.includes(id)) throw new Error('cycle: '+[...active.slice(active.indexOf(id)),id].join(' -> '));
    const r=map.get(id);if(!r) throw new Error('missing id: '+id);
    active.push(id);r.dependencies.forEach(visit);active.pop();done.add(id);result.push(id);
  }
  requestedIds.forEach(visit);return result;
}
export function reverseDependencies(records,id) {
  if(!records.some(r=>r.id===id)) throw new Error('unknown id: '+id);
  const reverse=new Map();
  for(const r of records) for(const dep of r.dependencies) {if(!reverse.has(dep)) reverse.set(dep,[]);reverse.get(dep).push(r.id);}
  const seen=new Set([id]);
  function visit(key) {for(const parent of reverse.get(key)||[]) if(!seen.has(parent)) {seen.add(parent);visit(parent);}}
  visit(id);seen.delete(id);return [...seen].sort();
}
"}

{"path":"src/transfer.mjs","content":"import {StringDecoder} from 'node:string_decoder';
import {parseCSV,stringifyCSV} from './csv.mjs';
import {normalizeRecord} from './catalog.mjs';
const header=['id','name','version','tags','dependencies'];
export function exportCSV(records) {
  return stringifyCSV([header,...records.map(r=>[r.id,r.name,r.version,r.tags.join('|'),r.dependencies.join('|')])]);
}
function commit(records,catalog) {
  const normalized=records.map(normalizeRecord);
  return catalog.applyBatch(normalized.map(record=>({type:'add',record})));
}
export function importCSV(text,catalog) {
  const rows=parseCSV(text);
  if(!rows.length || rows[0].length!==5 || rows[0].some((v,i)=>v!==header[i])) throw new Error('invalid CSV header');
  return commit(rows.slice(1).map(row=>{
    if(row.length!==5) throw new Error('invalid CSV row');
    return {id:row[0],name:row[1],version:row[2],tags:row[3]?row[3].split('|'):[],dependencies:row[4]?row[4].split('|'):[]};
  }),catalog);
}
export async function* exportNDJSON(records) {for(const r of records) yield JSON.stringify(r)+'\n';}
export async function importNDJSON(chunks,catalog) {
  const decoder=new StringDecoder('utf8');let pending='';const records=[];
  function consume(text) {
    pending+=text;let i;
    while((i=pending.indexOf('\n'))>=0) {const line=pending.slice(0,i);pending=pending.slice(i+1);if(line.trim()) records.push(JSON.parse(line));}
  }
  for await(const chunk of chunks) {
    if(Buffer.isBuffer(chunk)) consume(decoder.write(chunk));
    else if(typeof chunk==='string') {consume(decoder.end());consume(chunk);}
    else throw new Error('invalid NDJSON chunk');
  }
  consume(decoder.end());if(pending.trim()) records.push(JSON.parse(pending));
  return commit(records,catalog);
}
"}

{"path":"src/server.mjs","content":"import http from 'node:http';
import {pathToFileURL} from 'node:url';
import {createCatalog} from './catalog.mjs';
import {searchRecords} from './search.mjs';
import {planDependencies} from './graph.mjs';
import {exportCSV,importCSV,exportNDJSON,importNDJSON} from './transfer.mjs';
const MAX=1024*1024;
async function body(req) {
  let size=0;const chunks=[];
  for await(const chunk of req) {
    size+=chunk.length;
    if(size>MAX) {const e=new Error('body exceeds 1 MiB');e.status=413;throw e;}
    chunks.push(chunk);
  }
  return Buffer.concat(chunks).toString('utf8');
}
export function createServer(catalog) {
  return http.createServer(async(req,res)=>{
    const send=(status,value,type='application/json')=>{res.writeHead(status,{'content-type':type});res.end(type==='application/json'?JSON.stringify(value):value);};
    try {
      const url=new URL(req.url,'http://localhost'), path=url.pathname, method=req.method;
      if(method==='GET' && path==='/health') return send(200,{ok:true});
      if(method==='GET' && path==='/records') {
        const query={};
        for(const key of ['text','versionMin','versionMax','sortBy','order']) if(url.searchParams.has(key)) query[key]=url.searchParams.get(key);
        if(url.searchParams.has('tags')) query.tags=url.searchParams.get('tags').split(',');
        for(const key of ['offset','limit']) if(url.searchParams.has(key)) {
          const v=url.searchParams.get(key);if(!/^[0-9]+$/.test(v)) throw new Error('invalid '+key);query[key]=Number(v);
        }
        return send(200,searchRecords(catalog.list(),query));
      }
      if(method==='POST' && path==='/records') {
        const record=JSON.parse(await body(req));
        if(typeof record?.id==='string' && catalog.get(record.id.trim())) return send(409,{error:'duplicate id: '+record.id.trim()});
        return send(201,catalog.add(record));
      }
      if(path.startsWith('/records/') && ['GET','PATCH','DELETE'].includes(method)) {
        const id=decodeURIComponent(path.slice('/records/'.length));
        if(!catalog.get(id)) return send(404,{error:'unknown id: '+id});
        if(method==='GET') return send(200,catalog.get(id));
        if(method==='PATCH') return send(200,catalog.update(id,JSON.parse(await body(req))));
        catalog.remove(id);res.writeHead(204);return res.end();
      }
      if(method==='GET' && path==='/plan') return send(200,{ids:planDependencies(catalog.list(),(url.searchParams.get('ids')||'').split(',').filter(Boolean))});
      if(method==='GET' && path==='/export.csv') return send(200,exportCSV(catalog.list()),'text/csv');
      if(method==='POST' && path==='/import.csv') return send(201,{added:importCSV(await body(req),catalog).length});
      if(method==='POST' && path==='/import.ndjson') {
        const text=await body(req);return send(201,{added:(await importNDJSON([text],catalog)).length});
      }
      if(method==='GET' && path==='/export.ndjson') {
        let text='';for await(const line of exportNDJSON(catalog.list())) text+=line;
        return send(200,text,'application/x-ndjson');
      }
      send(404,{error:'unknown route'});
    } catch(error) {
      if(!res.headersSent) send(error.status||400,{error:error.message||'invalid request'});
      else res.end();
    }
  });
}
if(process.argv[1] && import.meta.url===pathToFileURL(process.argv[1]).href) {
  const port=Number(process.env.PORT||3000);
  createServer(createCatalog()).listen(port,()=>console.log('Package Catalog listening on '+port));
}
"}

{"path":"src/cli.mjs","content":"import {readFile,writeFile,rename,unlink} from 'node:fs/promises';
import {randomUUID} from 'node:crypto';
import {pathToFileURL} from 'node:url';
import {createCatalog} from './catalog.mjs';
import {searchRecords} from './search.mjs';
import {planDependencies} from './graph.mjs';
import {importCSV,exportCSV} from './transfer.mjs';
export async function main(args=process.argv.slice(2)) {
  const [command,...rest]=args, options={};
  const allowed={list:['text','tags'],add:['record'],remove:['id'],plan:['ids'],'import-csv':['input'],'export-csv':[]};
  if(!Object.hasOwn(allowed,command)) throw new Error('unknown command');
  for(let i=0;i<rest.length;i+=2) {
    const key=rest[i].slice(2);
    if(!rest[i].startsWith('--') || !['file',...allowed[command]].includes(key) || rest[i+1]===undefined || Object.hasOwn(options,key)) throw new Error('invalid option: '+rest[i]);
    options[key]=rest[i+1];
  }
  if(!options.file) throw new Error('--file is mandatory');
  let seed=[];
  try {seed=JSON.parse(await readFile(options.file,'utf8'));} catch(e) {if(e.code!=='ENOENT') throw e;}
  const catalog=createCatalog(seed);let output,write=false;
  const required=key=>{if(!options[key]) throw new Error('--'+key+' is mandatory');return options[key];};
  switch(command) {
    case 'list':output=searchRecords(catalog.list(),{text:options.text||'',tags:options.tags?options.tags.split(','):[]});break;
    case 'add':output=catalog.add(JSON.parse(required('record')));write=true;break;
    case 'remove':output=catalog.remove(required('id'));write=true;break;
    case 'plan':output={ids:planDependencies(catalog.list(),required('ids').split(','))};break;
    case 'import-csv':output={added:importCSV(await readFile(required('input'),'utf8'),catalog).length};write=true;break;
    case 'export-csv':output=exportCSV(catalog.list());break;
  }
  if(write) {
    const temp=options.file+'.'+randomUUID()+'.tmp';
    try {await writeFile(temp,JSON.stringify(catalog.list(),null,2)+'\n',{flag:'wx'});await rename(temp,options.file);}
    finally {await unlink(temp).catch(e=>{if(e.code!=='ENOENT') throw e;});}
  }
  process.stdout.write((command==='export-csv'?output:JSON.stringify(output))+'\n');
}
if(process.argv[1] && import.meta.url===pathToFileURL(process.argv[1]).href) {
  main().catch(e=>{process.stderr.write(e.message+'\n');process.exitCode=1;});
}
"}

